-- LAN-302 승인 WebP 652개의 CloudFront URL을 Writing 표현 예문 payload에 반영한다.
-- 실행 전: lan302-image-upload-manifest.csv의 모든 S3 객체가 업로드·검증되었는지 확인한다.
SELECT pg_advisory_xact_lock(hashtext('lan302-practice-example-image-urls'));
LOCK TABLE writing_expression IN SHARE ROW EXCLUSIVE MODE;

CREATE TEMP TABLE lan302_image_updates (
    expression_id BIGINT NOT NULL,
    scenario_id BIGINT NOT NULL,
    display_order INTEGER NOT NULL,
    example_index INTEGER NOT NULL CHECK (example_index BETWEEN 1 AND 4),
    image_url TEXT NOT NULL,
    PRIMARY KEY (expression_id, example_index),
    UNIQUE (scenario_id, display_order, example_index)
) ON COMMIT DROP;

