DO $$
DECLARE
    update_count INTEGER;
    matched_count INTEGER;
    invalid_expression_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO update_count FROM lan302_image_updates;
    IF update_count <> 652 THEN
        RAISE EXCEPTION 'LAN-302 requires 652 image updates, got %', update_count;
    END IF;

    SELECT COUNT(*) INTO matched_count
    FROM lan302_image_updates u
    JOIN writing_expression w
      ON w.id = u.expression_id
     AND w.scenario_id = u.scenario_id
     AND w.display_order = u.display_order
     AND w.target_locale = 'EN'
     AND w.base_locale = 'KR';
    IF matched_count <> 652 THEN
        RAISE EXCEPTION 'LAN-302 DB mapping mismatch: matched % of 652 image updates', matched_count;
    END IF;

    SELECT COUNT(*) INTO invalid_expression_count
    FROM (
        SELECT expression_id
        FROM lan302_image_updates
        GROUP BY expression_id
        HAVING COUNT(*) <> 4
    ) invalid_expression;
    IF invalid_expression_count <> 0 THEN
        RAISE EXCEPTION 'LAN-302 requires exactly four updates per expression';
    END IF;
END $$;
WITH update_urls AS (
    SELECT expression_id,
           jsonb_object_agg((example_index - 1)::TEXT, to_jsonb(image_url)) AS urls
    FROM lan302_image_updates
    GROUP BY expression_id
)
UPDATE writing_expression w
SET practice_examples_payload = patched.payload,
    updated_at = CURRENT_TIMESTAMP
FROM update_urls u
CROSS JOIN LATERAL (
    SELECT jsonb_agg(
               jsonb_set(example.value, ARRAY['imageUrl'], u.urls -> ((example.ordinality - 1)::TEXT), false)
               ORDER BY example.ordinality
           ) AS payload
    FROM jsonb_array_elements(w.practice_examples_payload) WITH ORDINALITY AS example(value, ordinality)
) patched
WHERE w.id = u.expression_id;

DO $$
DECLARE
    verified_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO verified_count
    FROM lan302_image_updates u
    JOIN writing_expression w ON w.id = u.expression_id
    WHERE w.practice_examples_payload -> (u.example_index - 1) ->> 'imageUrl' = u.image_url;
    IF verified_count <> 652 THEN
        RAISE EXCEPTION 'LAN-302 post-update verification failed: verified % of 652 URLs', verified_count;
    END IF;
END $$;
